<?php
namespace App\Http\Controllers; use App\Models\Finding; use App\Services\AnalysisAccess; use Illuminate\Http\Request;
class DashboardController extends Controller {public function __invoke(Request $r){$b=AnalysisAccess::query($r->user());return ['batches'=>['total'=>(clone $b)->count(),'processing'=>(clone $b)->whereIn('status',['uploading','queued','processing','retrying','cancelling'])->count(),'failed'=>(clone $b)->where('status','failed')->count()],'documents'=>(clone $b)->sum('document_count'),'items'=>(clone $b)->sum('item_count'),'open_findings'=>Finding::whereIn('analysis_batch_id',(clone $b)->select('id'))->whereIn('status',['open','in_review'])->selectRaw('severity,count(*) total')->groupBy('severity')->pluck('total','severity'),'recent_batches'=>(clone $b)->with('company:id,legal_name')->latest()->limit(10)->get()];}}
